import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate, useLocation, useNavigate } from 'react-router-dom';



import Login from './components/Clients/Auth/Login';
import Register from './components/Clients/Auth/Register';
import Dashboard from './components/DashboardLayout';
import ClientLayout from './components/ClientLayiut';
import ProtectedRoute from './components/Clients/Auth/ProtectedRoute';



function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const location = useLocation();
  const navigate = useNavigate();

  // Vérifier session
  useEffect(() => {
    const userData = localStorage.getItem('userData');
    if (userData) {
      const user = JSON.parse(userData);
      setUserRole(user.role);
      setIsAuthenticated(true);

      // Si admin → dashboard admin automatiquement
      if (user.role === 'admin' && location.pathname !== '/admin') {
        navigate('/admin', { replace: true });
      }
    }
    setIsLoading(false);
  }, []);

  // Connexion
  const handleLogin = (userData) => {
    localStorage.setItem('userData', JSON.stringify(userData));
    setUserRole(userData.role);
    setIsAuthenticated(true);

    if (userData.role === 'admin') {
      navigate('/admin', { replace: true });
    } else {
      navigate('/dashboard', { replace: true });
    }
  };

  // Déconnexion
  const handleLogout = () => {
    localStorage.removeItem('userData');
    setIsAuthenticated(false);
    setUserRole(null);
    navigate('/login', { replace: true });
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white dark:bg-neutral-950">
        <div className="text-center">
          <div className="h-12 w-12 border-4 border-primary-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
          <p className="mt-4 text-neutral-600 dark:text-neutral-400">Chargement...</p>
        </div>
      </div>
    );
  }

  // Cacher Header/Footer pour dashboard admin
  const hideUi = (userRole === 'admin') || location.pathname.startsWith('/dashboard');

  return (
    <>
      {!hideUi && <Header isAuthenticated={isAuthenticated} onLogout={handleLogout} />}

      <div className="min-h-screen bg-white dark:bg-neutral-950 text-neutral-900 dark:text-white">
        <Routes>
          {/* HOME / CLIENT */}
          <Route
            path="/"
            element={
              userRole === 'admin' ? <Navigate to="/admin" replace /> : <Home />
            }
          />
          <Route
            path="/contact"
            element={
              userRole === 'admin' ? <Navigate to="/admin" replace /> : <Contact />
            }
          />
          <Route
            path="/portfolio"
            element={
              userRole === 'admin' ? <Navigate to="/admin" replace /> : <Portfolio />
            }
          />
          <Route
            path="/services"
            element={
              userRole === 'admin' ? <Navigate to="/admin" replace /> : <Services />
            }
          />

          {/* LOGIN / REGISTER */}
          <Route
            path="/login"
            element={isAuthenticated ? (
              userRole === 'admin' ? <Navigate to="/admin" replace /> : <Navigate to="/dashboard" replace />
            ) : (
              <Login onLogin={handleLogin} />
            )}
          />
          <Route path="/register" element={<Register />} />

          {/* DASHBOARD USER */}
          <Route
            path="/dashboard/*"
            element={
              <ProtectedRoute isAuthenticated={isAuthenticated} requiredRole="user" userRole={userRole}>
                <Dashboard onLogout={handleLogout} />
              </ProtectedRoute>
            }
          />

          {/* DASHBOARD ADMIN */}
          <Route
            path="/admin/*"
            element={
              <ProtectedRoute isAuthenticated={isAuthenticated} requiredRole="admin" userRole={userRole}>
                <Dashboard onLogout={handleLogout} isAdmin={true} />
              </ProtectedRoute>
            }
          />

          {/* 404 */}
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </div>

      {!hideUi && <Footer />}
    </>
  );
}

export default function AppWrapper() {
  return (
    <Router>
      <App />
    </Router>
  );
}
